<script setup>
import { computed } from 'vue'
import { roleMeta, avatarUrl } from './config'

const props = defineProps({
  member: { type: Object, required: true },
  team: { type: Object, default: null },
  // Compact = the draggable card used inside the board columns.
  compact: { type: Boolean, default: false },
  draggable: { type: Boolean, default: false }
})

const emit = defineEmits(['edit', 'delete'])

const role = computed(() => roleMeta(props.member.category))
const avatar = computed(() => avatarUrl(props.member))
</script>

<template>
  <!-- ── Compact card (board columns) ─────────────────────────────────── -->
  <div
