    class="card bg-base-100 border border-base-content/10 rounded-lg p-2 cursor-pointer hover:border-base-content/30 transition-colors"
    :draggable="draggable"
    role="button"
    tabindex="0"
    :aria-label="`Edit ${member.name}`"
    @click="emit('edit', member)"
    @keydown.enter.prevent="emit('edit', member)"
    @keydown.space.prevent="emit('edit', member)"
  >
    <div class="flex items-center gap-2">
      <div class="avatar shrink-0">
        <div class="w-8 rounded-full">
          <img :src="avatar" :alt="member.name" />
        </div>
      </div>
      <div class="min-w-0">
        <div class="text-sm font-semibold truncate">{{ member.name }}</div>
        <div class="text-[11px] text-base-content/50 truncate flex items-center gap-1">
          <i :class="role.icon" class="text-[10px]"></i>{{ role.label }}
        </div>
      </div>
    </div>
  </div>

  <!-- ── Grid card ────────────────────────────────────────────────────── -->
  <article
    v-else
    class="group card bg-base-100 border border-base-content/10 rounded-xl overflow-hidden cursor-pointer hover:border-base-content/30 hover:bg-base-200/60 transition-colors"
    role="button"
    tabindex="0"
    :aria-label="`Edit ${member.name}`"
    @click="emit('edit', member)"
    @keydown.enter.prevent="emit('edit', member)"
    @keydown.space.prevent="emit('edit', member)"
  >
    <!-- Team colour strip -->
    <div class="h-1 w-full" :style="{ backgroundColor: team?.color || '#71717a' }"></div>

    <div class="p-3 flex flex-col gap-3">
      <div class="flex items-start gap-3">
        <div class="avatar shrink-0">
          <div class="w-11 rounded-full ring ring-base-300 ring-offset-1 ring-offset-base-100">
            <img :src="avatar" :alt="member.name" />
          </div>
        </div>

        <div class="min-w-0 flex-1">
          <h3 class="font-semibold text-sm truncate">{{ member.name }}</h3>
          <span class="badge badge-sm gap-1 mt-1" :class="role.badge">
            <i :class="role.icon" class="text-[10px]"></i>{{ role.label }}
          </span>
        </div>

        <div class="flex gap-1 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity">
          <button
            type="button"
            class="btn btn-ghost btn-xs btn-square"
            :title="`Edit ${member.name}`"
            @click.stop="emit('edit', member)"
          >
            <i class="fa-solid fa-pen text-xs"></i>
          </button>
          <button
            type="button"
            class="btn btn-ghost btn-xs btn-square text-error"
            :title="`Delete ${member.name}`"
            @click.stop="emit('delete', member)"
          >
            <i class="fa-solid fa-trash text-xs"></i>
          </button>
        </div>
      </div>

      <p class="text-xs text-base-content/60 leading-snug line-clamp-2 min-h-[2.25rem]">
        {{ member.description || 'No description yet' }}
      </p>

      <div class="flex items-center gap-3 text-[11px] text-base-content/50 border-t border-base-content/10 pt-2">
        <span class="inline-flex items-center gap-1" :class="member.use_knowledge ? 'text-info' : ''" title="Company knowledge">
          <i class="fa-solid fa-book"></i>{{ member.use_knowledge ? 'On' : 'Off' }}
        </span>
        <span class="inline-flex items-center gap-1" :class="member.tools?.length ? 'text-success' : ''" title="Skills">
          <i class="fa-solid fa-wrench"></i>{{ member.tools?.length || 0 }}
        </span>
        <span v-if="member.llm_model" class="inline-flex items-center gap-1 truncate" :title="member.llm_model">
          <i class="fa-solid fa-brain"></i>{{ member.llm_model }}
        </span>
      </div>
    </div>
  </article>
</template>
