<script>
import ChatLLMModelSelector from '@/components/chat/ChatLLMModelSelector.vue'
import { ROLE_META, roleMeta, avatarUrl } from './config'

// Ready-to-use personas so non-technical managers never face an empty prompt box.
const PERSONA_TEMPLATES = {
  lead: {
    label: 'Team Lead',
    content: [
      'You are the team lead for this workspace. You coordinate other members, break goals into tasks and review work before it is delivered.',
      '',
      '- Ask for missing context before starting.',
      '- Keep summaries short and action oriented.'
    ].join('\n')
  },
  support: {
    label: 'Support Agent',
    content: [
      'You are a friendly support agent. You answer customer questions clearly and empathetically.',
      '',
      '- Never invent policies — ask to check the knowledge base.',
      '- Escalate to a human when the request is sensitive.'
    ].join('\n')
  },
  engineer: {
    label: 'Engineer',
    content: [
      'You are a senior software engineer on the platform team. You write clean, tested code and explain trade-offs.',
      '',
      '- Prefer small, reviewable changes.',
      '- Always mention the tests that were run.'
    ].join('\n')
  },
  agent: {
    label: 'Autonomous Agent',
    content: [
      'You are an autonomous agent. You plan a short set of steps, execute them with your skills and report the results.',
      '',
      '- Stop and ask when a step is ambiguous.',
      '- Never take destructive actions without confirmation.'
    ].join('\n')
  }
}

export default {
  name: 'TeamMemberDrawer',
  components: { ChatLLMModelSelector },
  props: {
    /** Working copy source: the profile being edited. */
    member: { type: Object, required: true },
    /** All members, used by the "Works with" picker. */
    members: { type: Array, default: () => [] },
    /** Available skills (tools) as returned by the profiles API. */
    tools: { type: Array, default: () => [] },
    /** Departments (business teams). */
    teams: { type: Array, default: () => [] },
    /** Currently assigned department id. */
    teamId: { type: String, default: null },
    saving: { type: Boolean, default: false }
  },
  emits: ['save', 'delete', 'close'],
  data() {
    return {
      tab: 'about',
      draft: {},
      selectedTeamId: null,
      roleMetaMap: ROLE_META,
      personaTemplates: PERSONA_TEMPLATES,
      tabs: [
        { id: 'about', label: 'About', icon: 'fa-solid fa-user' },
        { id: 'persona', label: 'Persona', icon: 'fa-solid fa-wand-magic-sparkles' },
        { id: 'capabilities', label: 'Capabilities', icon: 'fa-solid fa-wrench' },
        { id: 'advanced', label: 'Advanced', icon: 'fa-solid fa-key' }
      ]
    }
  },
  computed: {
    role() {
      return roleMeta(this.draft.category)
    },
    avatar() {
      return avatarUrl(this.draft)
    },
    usedTools() {
      return this.draft.tools || []
    },
    // Skills grouped by their tag so the list stays scannable.
    toolGroups() {
      const groups = {}
      this.tools.forEach(tool => {
        const name = tool?.tool_json?.function?.name
        if (!name) return
        const tags = (tool.tags && tool.tags.length) ? tool.tags : ['General']
        tags.forEach(tag => {
          if (!groups[tag]) groups[tag] = []
          groups[tag].push({
            name,
            description: tool.tool_json.function.description,
            tags
          })
        })
      })
      return groups
    },
    fileMatchValid() {
      if (!this.draft.file_match) return true
      try {
        new RegExp(this.draft.file_match)
        return true
      } catch {
        return false
      }
    },
    linkableMembers() {
      return this.members.filter(m => m.name !== this.draft.name)
    },
    linkedProfiles() {
      return this.draft.profiles || []
    },
    apiNamePlaceholder() {
      const projectName = this.$project?.project_name || 'project'
      return `default: ${projectName}/${this.draft.name || ''}`
    }
  },
  watch: {
    member: {
      immediate: true,
      handler(member) {
        this.resetDraft(member)
      }
    },
    teamId: {
      immediate: true,
      handler(id) {
        this.selectedTeamId = id
      }
    }
  },
  mounted() {
    window.addEventListener('keydown', this.onKeydown)
  },
  beforeUnmount() {
    window.removeEventListener('keydown', this.onKeydown)
  },
  methods: {
    onKeydown(event) {
      if (event.key === 'Escape') this.$emit('close')
    },
    resetDraft(member) {
      const source = member || {}
      this.draft = {
        ...JSON.parse(JSON.stringify(source)),
        tools: [...(source.tools || [])],
        profiles: [...(source.profiles || [])],
        api_settings: {
          active: false,
          modelName: '',
          modelDescription: '',
          ...(source.api_settings || {})
        }
      }
      this.tab = 'about'
    },
    isToolSelected(name) {
      return this.usedTools.includes(name)
    },
    toggleTool(name) {
      this.draft.tools = this.isToolSelected(name)
        ? this.usedTools.filter(t => t !== name)
        : [...this.usedTools, name]
    },
    toggleProfile(name) {
      this.draft.profiles = this.linkedProfiles.includes(name)
        ? this.linkedProfiles.filter(p => p !== name)
        : [...this.linkedProfiles, name]
    },
    applyTemplate(key) {
      const tpl = this.personaTemplates[key]
      if (tpl) this.draft.content = tpl.content
    },
    submit() {
      if (!this.draft.name || !this.draft.name.trim() || this.saving) return
      this.$emit('save', { profile: this.draft, teamId: this.selectedTeamId })
    },
    requestDelete() {
      this.$emit('delete', { profile: this.draft })
    }
  }
}
</script>

<template>
  <div class="fixed inset-0 z-50 flex justify-end">
    <!-- Scrim -->
    <div class="absolute inset-0 bg-black/50 backdrop-blur-sm" @click="$emit('close')"></div>

    <!-- Panel -->
    <aside
      class="relative h-full w-full max-w-[30rem] bg-base-100 border-l border-base-content/10 shadow-2xl flex flex-col"
      role="dialog"
      aria-modal="true"
      :aria-label="`Edit ${draft.name || 'member'}`"
    >
      <!-- Header -->
      <header class="flex items-center gap-3 px-4 py-3 border-b border-base-content/10 shrink-0">
        <div class="avatar">
          <div class="w-10 rounded-full">
            <img :src="avatar" :alt="draft.name" />
          </div>
        </div>
        <div class="min-w-0">
          <div class="font-semibold truncate">{{ draft.name || 'New member' }}</div>
          <div class="text-xs text-base-content/50 flex items-center gap-1">
            <i :class="role.icon" class="text-[10px]"></i>{{ role.label }}
          </div>
        </div>
        <button type="button" class="btn btn-ghost btn-sm btn-square ml-auto" aria-label="Close editor" @click="$emit('close')">
          <i class="fa-solid fa-xmark"></i>
        </button>
      </header>

      <!-- Tabs -->
      <div role="tablist" class="tabs tabs-bordered px-2 shrink-0">
        <a
          v-for="t in tabs"
          :key="t.id"
          role="tab"
          class="tab gap-1"
          :class="tab === t.id ? 'tab-active font-semibold' : ''"
          @click="tab = t.id"
        >
          <i :class="t.icon" class="text-xs"></i>{{ t.label }}
        </a>
      </div>

      <!-- Body -->
      <div class="flex-1 min-h-0 overflow-y-auto p-4">
        <!-- ── About ─────────────────────────────────────────────── -->
        <div v-if="tab === 'about'" class="flex flex-col gap-4">
          <div>
            <label class="label-text text-xs font-semibold pb-1 block">Avatar URL</label>
            <input v-model="draft.avatar" type="text" class="input input-sm input-bordered w-full" placeholder="Paste an image URL (optional)" />
            <p class="text-[11px] text-base-content/40 mt-1">Leave empty to use an auto-generated avatar.</p>
          </div>

          <div>
            <label class="label-text text-xs font-semibold pb-1 block">Full name *</label>
            <input v-model="draft.name" type="text" class="input input-sm input-bordered w-full" placeholder="e.g. Ava Thompson" />
          </div>

          <div>
            <label class="label-text text-xs font-semibold pb-1 block">Role</label>
            <select v-model="draft.category" class="select select-sm select-bordered w-full">
              <option v-for="(meta, key) in roleMetaMap" :key="key" :value="key">
                {{ meta.label }} — {{ meta.hint }}
              </option>
            </select>
          </div>

          <div>
            <label class="label-text text-xs font-semibold pb-1 block">Team</label>
            <select v-model="selectedTeamId" class="select select-sm select-bordered w-full">
              <option v-for="t in teams" :key="t.id" :value="t.id">{{ t.name }}</option>
            </select>
          </div>

          <div>
            <label class="label-text text-xs font-semibold pb-1 block">Short description</label>
            <textarea v-model="draft.description" rows="3" class="textarea textarea-bordered textarea-sm w-full" placeholder="What does this teammate do?"></textarea>
          </div>
        </div>

        <!-- ── Persona ───────────────────────────────────────────── -->
        <div v-else-if="tab === 'persona'" class="flex flex-col gap-3">
          <div class="alert bg-primary/10 border-primary/20 py-2 text-xs gap-2">
            <i class="fa-solid fa-circle-info text-primary"></i>
            <span>Describe in plain language how this teammate should behave, what they focus on and any rules they must follow. This is their "personality".</span>
          </div>

          <div class="flex flex-wrap gap-2 items-center">
            <span class="text-xs text-base-content/50">Start from a template:</span>
            <button
              v-for="(tpl, key) in personaTemplates"
              :key="key"
              type="button"
              class="btn btn-xs btn-outline gap-1"
              @click="applyTemplate(key)"
            >
              <i class="fa-solid fa-wand-magic-sparkles text-[10px]"></i>{{ tpl.label }}
            </button>
          </div>

          <div>
            <label class="label-text text-xs font-semibold pb-1 block">Persona &amp; instructions</label>
            <textarea v-model="draft.content" rows="12" class="textarea textarea-bordered w-full text-sm" placeholder="You are a helpful teammate who…"></textarea>
            <div class="text-[11px] text-base-content/40 mt-1">{{ (draft.content || '').length }} characters</div>
          </div>

          <div>
            <div class="label-text text-xs font-semibold pb-1">Preview</div>
            <div class="rounded-lg bg-base-200 border border-base-content/10 p-3 min-h-[5rem]">
              <p class="text-sm whitespace-pre-wrap text-base-content/70">{{ draft.content || 'Nothing written yet.' }}</p>
            </div>
          </div>
        </div>

        <!-- ── Capabilities ──────────────────────────────────────── -->
        <div v-else-if="tab === 'capabilities'" class="flex flex-col gap-4">
          <div>
            <label class="label-text text-xs font-semibold pb-1 block">AI engine</label>
            <ChatLLMModelSelector :selectedModel="draft.llm_model" @model-changed="draft.llm_model = $event" />
            <p class="text-[11px] text-base-content/40 mt-1">The model that powers this teammate's responses.</p>
          </div>

          <div class="flex items-center gap-3 p-3 rounded-lg bg-base-200 border border-base-content/10">
            <i class="fa-solid fa-book text-info"></i>
