<script>
import TeamMemberCard from '@/components/team-view/TeamMemberCard.vue'
import TeamMemberDrawer from '@/components/team-view/TeamMemberDrawer.vue'
import AddTeamMemberDialog from '@/components/team-view/AddTeamMemberDialog.vue'
import {
  DEFAULT_TEAMS,
  ROLE_META,
  roleMeta,
  loadAssignments,
  saveAssignments,
  defaultTeamId,
  avatarUrl
} from '@/components/team-view/config'

// Defaults for a freshly created profile (matches the shape EditProfile expects).
const EMPTY_GUARDRAILS = {
  enabled: false,
  scope: '',
  scope_keywords: [],
  scope_similarity_threshold: 0.35,
  allowed_tools: [],
  refusal_message: 'I can only answer questions within my configured scope.',
  risk_threshold: 10.0,
  use_llm_classifier: false
}

export default {
  name: 'TeamView',
  components: { TeamMemberCard, TeamMemberDrawer, AddTeamMemberDialog },
  // `params` is passed by dockview in desktop mode (config/apps.js → desktopParams).
  props: ['params'],
  data() {
    return {
      teams: DEFAULT_TEAMS,
      assignments: {},
      members: [],
      tools: [],
      loading: true,
      error: null,
      view: 'grid', // grid | board
      search: '',
      roleFilter: '',
      teamFilter: '',
      sort: 'name',
      selectedMember: null,
      selectedTeamId: null,
      addOpen: false,
      confirmDelete: null,
      saving: false,
      dragging: null,
      roleMetaMap: ROLE_META
    }
  },
  computed: {
    project() {
      return this.$project
    },
    filteredMembers() {
      const q = (this.search || '').trim().toLowerCase()
      const list = this.members.filter(member => {
        const matchSearch = !q ||
          [member.name, member.description, member.category].join(' ').toLowerCase().includes(q)
        const matchRole = !this.roleFilter || member.category === this.roleFilter
        const matchTeam = !this.teamFilter || this.memberTeamId(member) === this.teamFilter
        return matchSearch && matchRole && matchTeam
      })

      return [...list].sort((a, b) => {
        if (this.sort === 'role') {
          return roleMeta(a.category).label.localeCompare(roleMeta(b.category).label)
        }
        return (a.name || '').localeCompare(b.name || '')
      })
    },
    groupedMembers() {
      return this.teams
        .map(team => ({ team, members: this.membersOf(team.id) }))
        .filter(group => group.members.length)
    },
    stats() {
      const skills = new Set(this.members.flatMap(m => m.tools || []))
      return {
        members: this.members.length,
        teams: this.teams.length,
        skills: skills.size,
        knowledge: this.members.filter(m => m.use_knowledge).length
      }
    },
    hasResults() {
      return this.filteredMembers.length > 0
    },
    hasFilters() {
      return !!(this.search || this.roleFilter || this.teamFilter)
    }
  },
  watch: {
    // Reload when the active project changes (mobile project switch / desktop panel).
    $project: {
      handler() {
        this.load()
      }
    }
  },
  created() {
    // A specific team can be deep-linked ("/:projectName/team/:teamId").
    const teamId = this.$route?.params?.teamId
      || this.params?.teamId
      || this.params?.params?.teamId
      || null
    if (teamId && this.teams.some(t => t.id === teamId)) {
      this.teamFilter = teamId
    }
    this.load()
  },
  methods: {
    avatarUrl,

    // ── Data ──────────────────────────────────────────────────────────────
    async load() {
      const project = this.$project
      if (!project?.$api) {
        // Project not ready yet — the `$project` watcher will retry.
        this.loading = false
        return
      }
      this.loading = true
      this.error = null
      try {
        const [members, tools] = await Promise.all([
          project.$api.profiles.list(),
          project.$api.profiles.tools().catch(() => [])
        ])
        this.members = members || []
        this.tools = tools || []
        this.assignments = loadAssignments(project.project_id)
      } catch (e) {
        console.error('[TeamView] Failed to load team', e)
        this.error = e?.message || 'Failed to load your team'
      } finally {
        this.loading = false
      }
    },
    async reloadMembers() {
      const list = await this.$project.$api.profiles.list()
      this.members = list || []
    },

    // ── Grouping ──────────────────────────────────────────────────────────
    memberTeamId(member) {
      return this.assignments[member.name] || defaultTeamId(member)
    },
    membersOf(teamId) {
      return this.filteredMembers.filter(member => this.memberTeamId(member) === teamId)
    },
    moveMemberToTeam(memberName, teamId) {
      const member = this.members.find(m => m.name === memberName)
      if (!member || this.memberTeamId(member) === teamId) return
      this.assignments = { ...this.assignments, [memberName]: teamId }
      saveAssignments(this.$project.project_id, this.assignments)
      const team = this.teams.find(t => t.id === teamId)
      this.$ui.addNotification({ text: `“${memberName}” moved to ${team?.name || 'the team'}`, type: 'success' })
    },

    // ── Editor ────────────────────────────────────────────────────────────
    openEditor(member) {
      this.selectedMember = member
      this.selectedTeamId = this.memberTeamId(member)
    },
    closeEditor() {
      this.selectedMember = null
      this.selectedTeamId = null
    },
    async saveMember({ profile, teamId }) {
      if (!profile?.name?.trim() || this.saving) return
      this.saving = true
      try {
        const previousName = this.selectedMember?.name
        await this.$project.$api.profiles.save(profile)

        // Keep the client-side department assignment in sync (incl. renames).
        if (previousName && previousName !== profile.name) {
          delete this.assignments[previousName]
        }
        if (teamId) this.assignments[profile.name] = teamId
        saveAssignments(this.$project.project_id, this.assignments)
        this.assignments = { ...this.assignments }

        await this.reloadMembers()
        this.closeEditor()
        this.$ui.addNotification({ text: `Changes to “${profile.name}” saved`, type: 'success' })
      } catch (e) {
        console.error('[TeamView] Failed to save member', e)
        this.$ui.addNotification({ text: 'Failed to save member', type: 'error' })
      } finally {
        this.saving = false
      }
    },

    // ── Add ───────────────────────────────────────────────────────────────
    openAdd() {
      this.addOpen = true
    },
    async addMember(payload) {
      if (!payload?.name || this.saving) return
      this.saving = true
      try {
        const profile = {
          name: payload.name.trim(),
          category: payload.category,
          avatar: '',
          description: payload.description || '',
          content: payload.content || '',
          llm_model: '',
          file_match: '',
          profiles: [],
          tools: [],
          use_knowledge: false,
          api_settings: { active: false, modelName: '', modelDescription: '' },
          guardrails: { ...EMPTY_GUARDRAILS },
          project_id: this.$project.project_id
        }
        await this.$project.$api.profiles.save(profile)

        if (payload.teamId) {
          this.assignments = { ...this.assignments, [profile.name]: payload.teamId }
          saveAssignments(this.$project.project_id, this.assignments)
        }

        await this.reloadMembers()
        this.addOpen = false
        this.$ui.addNotification({ text: `“${profile.name}” added to the team`, type: 'success' })
      } catch (e) {
        console.error('[TeamView] Failed to add member', e)
        this.$ui.addNotification({ text: 'Failed to add member', type: 'error' })
      } finally {
        this.saving = false
      }
    },

    // ── Delete ────────────────────────────────────────────────────────────
    askDelete(payload) {
      this.confirmDelete = payload?.profile || payload
    },
    async deleteMember() {
      const member = this.confirmDelete
      if (!member || this.saving) return
      this.saving = true
      try {
        await this.$project.$api.profiles.delete(member.name)

        if (this.assignments[member.name]) {
          delete this.assignments[member.name]
          saveAssignments(this.$project.project_id, this.assignments)
          this.assignments = { ...this.assignments }
        }

        await this.reloadMembers()
        if (this.selectedMember?.name === member.name) this.closeEditor()
        this.confirmDelete = null
        this.$ui.addNotification({ text: `“${member.name}” removed`, type: 'success' })
      } catch (e) {
        console.error('[TeamView] Failed to remove member', e)
        this.$ui.addNotification({ text: 'Failed to remove member', type: 'error' })
      } finally {
        this.saving = false
      }
    },

    // ── Board drag & drop ─────────────────────────────────────────────────
    onDragStart(member) {
      this.dragging = member.name
    },
    onDragEnd() {
      this.dragging = null
    },
    onDrop(teamId) {
      if (this.dragging) {
        this.moveMemberToTeam(this.dragging, teamId)
        this.dragging = null
      }
    },

    clearFilters() {
      this.search = ''
      this.roleFilter = ''
      this.teamFilter = ''
    }
  }
}
</script>

<template>
  <div class="h-full w-full flex flex-col bg-base-100 overflow-hidden">
    <!-- ── Header ───────────────────────────────────────────────────────── -->
    <header class="shrink-0 border-b border-base-content/10 bg-base-100/60 backdrop-blur px-4 md:px-6 py-4">
      <div class="flex items-center gap-3 flex-wrap">
        <div class="flex items-center gap-3 mr-auto">
          <div class="w-10 h-10 rounded-xl grid place-items-center bg-primary/15 text-primary">
            <i class="fa-solid fa-people-group text-lg"></i>
          </div>
          <div>
            <h1 class="text-lg font-bold leading-tight">Your Team</h1>
            <p class="text-xs text-base-content/50 hidden sm:block">
              Describe who your AI teammates are, what they do and how they behave
            </p>
          </div>
        </div>

        <div class="join">
          <button
            type="button"
            class="join-item btn btn-sm"
            :class="view === 'grid' ? 'btn-active' : ''"
            title="Group by team"
            @click="view = 'grid'"
          >
            <i class="fa-solid fa-table-cells-large"></i>
            <span class="hidden sm:inline">By team</span>
          </button>
          <button
            type="button"
            class="join-item btn btn-sm"
            :class="view === 'board' ? 'btn-active' : ''"
            title="Board view"
            @click="view = 'board'"
          >
            <i class="fa-solid fa-table-columns"></i>
            <span class="hidden sm:inline">Board</span>
          </button>
        </div>

        <button type="button" class="btn btn-sm btn-primary" @click="openAdd">
          <i class="fa-solid fa-plus"></i>
          <span class="hidden sm:inline">Add member</span>
        </button>
      </div>
    </header>

    <!-- ── Stats ────────────────────────────────────────────────────────── -->
    <section class="shrink-0 px-4 md:px-6 pt-4">
      <div class="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <div class="card bg-base-200 border border-base-content/10 p-3 flex-row items-center gap-3">
          <div class="w-9 h-9 rounded-lg grid place-items-center bg-primary/15 text-primary">
            <i class="fa-solid fa-users"></i>
          </div>
          <div>
            <div class="text-xl font-bold leading-none">{{ stats.members }}</div>
            <div class="text-[11px] text-base-content/50 mt-1">Members</div>
          </div>
        </div>
        <div class="card bg-base-200 border border-base-content/10 p-3 flex-row items-center gap-3">
          <div class="w-9 h-9 rounded-lg grid place-items-center bg-info/15 text-info">
            <i class="fa-solid fa-table-cells-large"></i>
          </div>
          <div>
            <div class="text-xl font-bold leading-none">{{ stats.teams }}</div>
            <div class="text-[11px] text-base-content/50 mt-1">Teams</div>
          </div>
        </div>
        <div class="card bg-base-200 border border-base-content/10 p-3 flex-row items-center gap-3">
          <div class="w-9 h-9 rounded-lg grid place-items-center bg-success/15 text-success">
            <i class="fa-solid fa-wrench"></i>
          </div>
          <div>
            <div class="text-xl font-bold leading-none">{{ stats.skills }}</div>
            <div class="text-[11px] text-base-content/50 mt-1">Skills in use</div>
          </div>
        </div>
