  if ($state.profiles && $state.profiles.length > 0 && !forceReload) return
  const profiles = await promiseOrDefault(() => $api.profiles.list(), [])
  if (profiles && profiles.length > 0) {
    $state.profiles = profiles
    $state._mentionList = null
  }
}

